/**
 * 腾讯地图微信小程序SDK - 精简版
 * 仅包含 reverseGeocoder 逆地址解析功能
 * 基于腾讯位置服务 WebService API
 * 使用 uni.request 替代 wx.request，兼容 uni-app
 */
class QQMapWX {
  constructor(options) {
    this.key = options.key;
  }

  reverseGeocoder(options) {
    const that = this;
    const location = options.location;
    let url = 'https://apis.map.qq.com/ws/geocoder/v1/?key=' + that.key + '&get_poi=0';
    
    if (location) {
      url += '&location=' + location.latitude + ',' + location.longitude;
    }

    console.log('[QQMapWX] 请求URL:', url);

    uni.request({
      url: url,
      method: 'GET',
      dataType: 'json',
      success: function(res) {
        console.log('[QQMapWX] 响应状态码:', res.statusCode);
        console.log('[QQMapWX] 响应数据:', JSON.stringify(res.data));
        
        if (res.statusCode === 200 && res.data && res.data.status === 0) {
          if (options.success) {
            options.success(res.data);
          }
        } else {
          var errMsg = '请求失败';
          var errStatus = -1;
          if (res.data) {
            errStatus = res.data.status;
            errMsg = res.data.message || ('错误码:' + res.data.status);
          }
          console.error('[QQMapWX] 解析失败, status=' + errStatus + ', msg=' + errMsg);
          if (options.fail) {
            options.fail({
              status: errStatus,
              message: errMsg
            });
          }
        }
      },
      fail: function(err) {
        console.error('[QQMapWX] 网络请求失败:', err);
        if (options.fail) {
          options.fail({
            status: -1,
            message: '网络请求失败: ' + (err.errMsg || JSON.stringify(err))
          });
        }
      }
    });
  }
}

module.exports = QQMapWX;
